Rules.InvariantScript:
UpdateContext({var_load: true});
Set(
    varPDF,
    PDF(
        RelatorioContainer_2,
        {
            ExpandContainers: true,
            Orientation: "Portrait",
            Margin: "20"
        }
    )
);
UpdateContext(
    {
        varResposta: 'PowerAppV2->Criararquivo,Criarlinkdecompartilhamentoparaum...'.Run(
            "Vistoria de Veículos",
            {
                file: {
                    contentBytes: varPDF,
                    // passe o BLOB aqui
                    name: "Relatorio.pdf"// defina o nome do arquivo
                }
            }
        )
    }
);
UpdateContext({var_loadSave: true});

Download(varResposta.url);
UpdateContext(
    {
        var_loadSave: false,
        var_load: false
    }
);
